// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


/**
 * An open workspace database.
 *
 * Two connections. Every write, and most reads, go through `connection`,
 * whose `data_version` the apps poll. `reader` serves the reads a client
 * makes off its main thread (the next-up snapshot), so a main-thread read
 * does not queue behind them on one lock. It is `query_only` and never
 * holds a transaction open between calls, so under WAL each of its reads
 * sees every commit made before it began, the handle's own included, and it
 * cannot move the writer's `data_version`: reads do not commit.
 */
public interface CoreWorkspaceInterface {
    
    /**
     * The workspace `workspace_id` written out as `format`, stamped
     * `exported_at_ms`; absent when there is no such workspace.
     */
    fun `exportWorkspace`(`workspaceId`: kotlin.String, `format`: ExportFormat, `exportedAtMs`: kotlin.Long): kotlin.String?
    
    /**
     * Settles the session left paused when the app last went away: closes
     * it, crediting its seconds at the moment it was paused, as one "Log
     * Daily Progress" step, or discards it. `resolveStaleFocusSession`.
     */
    fun `resolveStaleFocusSession`(`nowMs`: kotlin.Long, `zone`: kotlin.String, `rolloverHour`: kotlin.UByte, `context`: FocusContext): StaleFocusOutcome
    
    /**
     * Today against the week, read and summed in the core.
     */
    fun `workProgress`(`nowMs`: kotlin.Long, `zone`: kotlin.String, `firstWeekday`: kotlin.UByte): WorkProgressTotals
    
    /**
     * The newest session that has not finished.
     */
    fun `activeFocusSession`(): SessionRow?
    
    /**
     * The live dailies in order.
     */
    fun `allDailies`(): List<DailyRow>
    
    /**
     * Every metadata row.
     */
    fun `allMetadata`(): List<MetadataRow>
    
    /**
     * Tasks completed since `since`, newest first.
     */
    fun `completedTasksSince`(`sinceMs`: kotlin.Long, `limit`: kotlin.Long): List<TaskRow>
    
    /**
     * Where a completion now falls in its day and in a run of days.
     */
    fun `completionContext`(`nowMs`: kotlin.Long, `zone`: kotlin.String): CompletionContext
    
    /**
     * One condition by id.
     */
    fun `condition`(`id`: kotlin.String): ConditionRow?
    
    /**
     * A workspace's conditions, oldest first.
     */
    fun `conditions`(`workspaceId`: kotlin.String): List<ConditionRow>
    
    /**
     * One contribution by id.
     */
    fun `contribution`(`id`: kotlin.String): ContributionRow?
    
    /**
     * A daily's contributions on the given days, oldest first.
     */
    fun `contributions`(`dailyId`: kotlin.String, `dayKeys`: List<kotlin.String>): List<ContributionRow>
    
    /**
     * The dailies the local day `day_ms` falls on shows, with their tasks and
     * that day's contributions.
     */
    fun `dailiesOn`(`dayMs`: kotlin.Long, `zone`: kotlin.String): List<DayDaily>
    
    /**
     * One daily by id, archived or not.
     */
    fun `daily`(`id`: kotlin.String): DailyRow?
    
    /**
     * A task's live daily, if it has one.
     */
    fun `dailyForTask`(`taskId`: kotlin.String): DailyRow?
    
    /**
     * One award by id.
     */
    fun `focusAward`(`id`: kotlin.String): AwardRow?
    
    /**
     * Awards in `[from, to)`, newest first.
     */
    fun `focusAwardsBetween`(`fromMs`: kotlin.Long, `toMs`: kotlin.Long): List<AwardRow>
    
    /**
     * Points today, over the last seven days and ever.
     */
    fun `focusPointsSummary`(`todayMs`: kotlin.Long, `tomorrowMs`: kotlin.Long, `weekStartMs`: kotlin.Long): PointsSummary
    
    /**
     * A session's queue in order, with each task.
     */
    fun `focusQueue`(`sessionId`: kotlin.String): List<QueueEntry>
    
    /**
     * One session by id.
     */
    fun `focusSession`(`id`: kotlin.String): SessionRow?
    
    /**
     * Whether any task is pinned in Today's order.
     */
    fun `hasManualFocusOrder`(): kotlin.Boolean
    
    /**
     * Every saved board's columns.
     */
    fun `kanbanBoards`(): List<BoardBaseline>
    
    /**
     * Seconds logged per task.
     */
    fun `loggedWork`(): List<LoggedWork>
    
    /**
     * A task's metadata row, if it has one.
     */
    fun `metadata`(`taskId`: kotlin.String): MetadataRow?
    
    /**
     * The metadata rows of the given tasks.
     */
    fun `metadataForTasks`(`taskIds`: List<kotlin.String>): List<MetadataRow>
    
    /**
     * The metadata rows that carry planning or a start time.
     */
    fun `planningMetadata`(): List<MetadataRow>
    
    /**
     * Every preference.
     */
    fun `preferences`(): List<PreferenceRow>
    
    /**
     * The newest awards.
     */
    fun `recentFocusAwards`(`limit`: kotlin.Long): List<AwardRow>
    
    /**
     * When tasks were completed in `[from, to)`.
     */
    fun `taskCompletionsBetween`(`fromMs`: kotlin.Long, `toMs`: kotlin.Long): List<kotlin.Long>
    
    /**
     * Open and closed task counts.
     */
    fun `taskCounts`(): TaskCounts
    
    /**
     * When tasks were created in `[from, to)`.
     */
    fun `taskCreationsBetween`(`fromMs`: kotlin.Long, `toMs`: kotlin.Long): List<kotlin.Long>
    
    /**
     * Tasks closed in `[from, to)`, oldest first.
     */
    fun `tasksClosedBetween`(`fromMs`: kotlin.Long, `toMs`: kotlin.Long): List<TaskRow>
    
    /**
     * The stored themes by id.
     */
    fun `themes`(): List<ThemeRow>
    
    /**
     * The metadata rows of waiting tasks and their follow-ups.
     */
    fun `waitingMetadata`(): List<MetadataRow>
    
    /**
     * Work blocks recorded in `[from, to)`.
     */
    fun `workBlocksBetween`(`fromMs`: kotlin.Long, `toMs`: kotlin.Long): List<WorkBlockRow>
    
    /**
     * A task's work blocks, oldest first.
     */
    fun `workBlocksForTask`(`taskId`: kotlin.String): List<WorkBlockRow>
    
    /**
     * Forgets the outbox entries the server has accepted.
     */
    fun `acknowledgeSyncChanges`(`throughSeq`: kotlin.Long)
    
    /**
     * Queues a task in a focus session.
     */
    fun `addToFocusQueue`(`sessionId`: kotlin.String, `taskId`: kotlin.String, `plannedSeconds`: kotlin.Long?, `nowMs`: kotlin.Long)
    
    /**
     * Copies a task's planning onto its subtasks as one step.
     */
    fun `applyPlanningToDescendants`(`taskId`: kotlin.String, `nowMs`: kotlin.Long, `zone`: kotlin.String)
    
    /**
     * Writes a pull into the workspace; whether anything changed.
     */
    fun `applyRemoteRows`(`rows`: List<IncomingRow>, `cursor`: kotlin.Long, `hlc`: kotlin.String?, `nowMs`: kotlin.Long): kotlin.Boolean
    
    /**
     * Archives a task's daily as one "Archive Daily" step.
     */
    fun `archiveDaily`(`taskId`: kotlin.String, `nowMs`: kotlin.Long)
    
    /**
     * Ranks tasks in Today's focus order as one "Reorder Today" step.
     */
    fun `arrangeDay`(`orderedTaskIds`: List<kotlin.String>, `nowMs`: kotlin.Long)
    
    /**
     * Pairs the store with a sync server.
     */
    fun `beginSync`(`deviceId`: kotlin.String, `serverUrl`: kotlin.String)
    
    /**
     * The workspace, made on first launch with its Inbox and conditions;
     * returns its id.
     */
    fun `bootstrap`(`nowMs`: kotlin.Long): kotlin.String
    
    /**
     * Banks a running block's time.
     */
    fun `checkpointFocusSession`(`id`: kotlin.String, `nowMs`: kotlin.Long)
    
    /**
     * The children of a task in a list, or its roots, in outline order.
     */
    fun `childTasks`(`listId`: kotlin.String, `parentTaskId`: kotlin.String?): List<TaskRow>
    
    /**
     * Un-ticks a day of a daily as one "Clear Daily" step.
     */
    fun `clearContribution`(`dailyId`: kotlin.String, `dayMs`: kotlin.Long, `zone`: kotlin.String)
    
    /**
     * Clears the focus order as one "Clear Focus Order" step.
     */
    fun `clearFocusOrder`(`nowMs`: kotlin.Long)
    
    /**
     * A combined scope's board — Everything's or a folder's — selected and
     * walked here, so only the rows it draws cross. See `board.rs`.
     */
    fun `combinedBoard`(`listIds`: List<kotlin.String>, `hideCompletedBeforeMs`: kotlin.Long?): BoardRead
    
    /**
     * Turns a standalone list into a task in the Inbox; returns the task's id.
     */
    fun `convertListToTask`(`id`: kotlin.String, `nowMs`: kotlin.Long): kotlin.String
    
    /**
     * Creates a condition as one "New Condition" step; returns its id.
     */
    fun `createCondition`(`workspaceId`: kotlin.String, `name`: kotlin.String, `isLocation`: kotlin.Boolean, `nowMs`: kotlin.Long): kotlin.String
    
    /**
     * Creates a folder as one "New Folder" step.
     */
    fun `createFolder`(`workspaceId`: kotlin.String, `name`: kotlin.String, `parentFolderId`: kotlin.String?, `nowMs`: kotlin.Long): CreatedItem
    
    /**
     * Creates a list as one "New List" step.
     */
    fun `createList`(`workspaceId`: kotlin.String, `name`: kotlin.String, `folderId`: kotlin.String?, `nowMs`: kotlin.Long): CreatedItem
    
    /**
     * Creates a task as one "New Task" step and returns its id.
     */
    fun `createTask`(`task`: NewTask, `nowMs`: kotlin.Long): kotlin.String
    
    /**
     * SQLite's `data_version` on this handle's connection: it moves when
     * another connection commits (the CLI, another process) and never for
     * this handle's own writes, so a client that writes only through the
     * core can poll it to learn that someone else changed the file.
     */
    fun `dataVersion`(): kotlin.Long
    
    /**
     * Deletes a folder as one "Delete Folder" step; its lists move to the top.
     */
    fun `deleteFolder`(`id`: kotlin.String)
    
    /**
     * Deletes a list and its tasks as one "Delete List" step.
     */
    fun `deleteList`(`id`: kotlin.String): DeletedList
    
    /**
     * Deletes a task and its subtree as one "Delete Task" step.
     */
    fun `deleteTask`(`id`: kotlin.String): DeletedTask
    
    /**
     * Removes a theme; whether there was one.
     */
    fun `deleteTheme`(`id`: kotlin.String): kotlin.Boolean
    
    /**
     * A task's editable state, as the editor opens it.
     */
    fun `editorSnapshot`(`taskId`: kotlin.String): EditorSnapshot
    
    /**
     * Unpairs: stops recording and forgets what was waiting to be sent.
     */
    fun `endSync`()
    
    /**
     * Queues every existing row for the first push after pairing.
     */
    fun `enqueueSyncSnapshot`(`nowMs`: kotlin.Long)
    
    /**
     * Finishes the block in hand as one step: "Complete Task", or "Log Daily
     * Progress" when the task stays open.
     */
    fun `finishFocusBlock`(`sessionId`: kotlin.String, `elapsedSeconds`: kotlin.Long, `qualityMultiplier`: kotlin.Double?, `completeTask`: kotlin.Boolean, `expectedBlockId`: kotlin.String?, `context`: FocusContext, `nowMs`: kotlin.Long, `zone`: kotlin.String): BlockFinished
    
    /**
     * Ends a focus session.
     */
    fun `finishFocusSession`(`id`: kotlin.String, `nowMs`: kotlin.Long)
    
    /**
     * A workspace's folders in sidebar order.
     */
    fun `folders`(`workspaceId`: kotlin.String): List<FolderRow>
    
    /**
     * Whether a session waiting on a blocked queue can resume in `context`.
     */
    fun `hasResumableFocusQueueTask`(`context`: FocusContext, `nowMs`: kotlin.Long, `zone`: kotlin.String): kotlin.Boolean
    
    /**
     * The task and list the next undo (`for_undo`) or redo affects.
     */
    fun `historyTarget`(`forUndo`: kotlin.Boolean): HistoryTarget
    
    /**
     * Brings the plugin-era dailies in once; how many it made.
     */
    fun `importLegacyDailies`(`legacy`: List<LegacyDailySeed>, `progressTaskIds`: List<kotlin.String>, `nowMs`: kotlin.Long): kotlin.UInt
    
    /**
     * Copies tasks from an outside service into the workspace, safely re-run,
     * outside the undo journal.
     */
    fun `importTasks`(`workspaceId`: kotlin.String, `listName`: kotlin.String, `sourceSystem`: kotlin.String, `seeds`: List<ImportedTaskSeed>, `nowMs`: kotlin.Long): ImportOutcome?
    
    /**
     * A workspace's Inbox.
     */
    fun `inbox`(`workspaceId`: kotlin.String): ListRow?
    
    /**
     * Indents a task under the sibling above as one "Indent Task" step.
     */
    fun `indentTask`(`id`: kotlin.String, `nowMs`: kotlin.Long)
    
    /**
     * Seeds the saved boards from the old preferences and the defaults;
     * returns every board.
     */
    fun `kanbanBoardBaseline`(`legacy`: List<BoardBaseline>, `currentKey`: kotlin.String): List<BoardBaseline>
    
    /**
     * The newest outbox entry, or nothing when nothing is waiting.
     */
    fun `latestSyncOutboxSeq`(): kotlin.Long?
    
    /**
     * One list, if it exists.
     */
    fun `list`(`id`: kotlin.String): ListRow?
    
    /**
     * A workspace's lists in sidebar order.
     */
    fun `lists`(`workspaceId`: kotlin.String, `includingArchived`: kotlin.Boolean): List<ListRow>
    
    /**
     * Logs progress on a daily as one "Log Daily" step; returns the
     * contribution's id.
     */
    fun `logContribution`(`dailyId`: kotlin.String, `seconds`: kotlin.Long, `complete`: kotlin.Boolean, `nowMs`: kotlin.Long, `zone`: kotlin.String): kotlin.String
    
    /**
     * Makes a task a daily as one "Make Daily" step; returns the daily's id.
     */
    fun `makeDaily`(`taskId`: kotlin.String, `weekdays`: List<kotlin.UInt>, `intervalDays`: kotlin.Long?, `targetSeconds`: kotlin.Long?, `nowMs`: kotlin.Long): kotlin.String
    
    /**
     * Moves a folder into another (or to the top) as one "Move Folder" step.
     */
    fun `moveFolder`(`id`: kotlin.String, `parentFolderId`: kotlin.String?, `nowMs`: kotlin.Long)
    
    /**
     * Moves a folder among its siblings as one "Reorder Folder" step.
     */
    fun `moveFolderWithinSiblings`(`id`: kotlin.String, `offset`: kotlin.Int, `nowMs`: kotlin.Long)
    
    /**
     * Moves a list into a folder (or to the top) as one "Move List" step.
     */
    fun `moveList`(`id`: kotlin.String, `folderId`: kotlin.String?, `nowMs`: kotlin.Long)
    
    /**
     * Moves a list among its siblings as one "Reorder List" step.
     */
    fun `moveListWithinFolder`(`id`: kotlin.String, `offset`: kotlin.Int, `nowMs`: kotlin.Long)
    
    /**
     * Moves a task and its subtree as one "Move Task" step.
     */
    fun `moveTask`(`id`: kotlin.String, `listId`: kotlin.String, `parentTaskId`: kotlin.String?, `toVisibleRoot`: kotlin.Boolean, `nowMs`: kotlin.Long)
    
    /**
