     */
    fun `renameFolder`(`id`: kotlin.String, `name`: kotlin.String, `nowMs`: kotlin.Long)
    
    /**
     * Renames a list as one "Rename List" step.
     */
    fun `renameList`(`id`: kotlin.String, `name`: kotlin.String, `nowMs`: kotlin.Long)
    
