     */
    fun `resumeEligibleFocusQueue`(`context`: FocusContext, `nowMs`: kotlin.Long, `zone`: kotlin.String): kotlin.Boolean
    
    /**
     * Resumes a paused block.
     */
    fun `resumeFocusSession`(`id`: kotlin.String, `nowMs`: kotlin.Long)
    
