        val `count`: kotlin.UInt) : PeriodicCadence()
        
    {
        

        companion object
    }
    
    data class Weeks(
        val `count`: kotlin.UInt) : PeriodicCadence()
        
    {
        

        companion object
    }
    
    /**
     * Monday to Friday, skipping the weekend.
     */
    object Weekdays : PeriodicCadence()
    
    
    /**
     * 1 = Sunday through 7 = Saturday, as Foundation counts them.
     */
    data class Weekday(
        val `weekday`: kotlin.UInt) : PeriodicCadence()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

